Q: How can I update a Json record in Dom for each person, when their unique id is there twice, but under two different dates? A: <p>Please cache and loop</p>
<p>Version 1, jQuery</p>
<pre><code>$.each(jsondata, (_, record) =&gt; {
  const $row = $('#' + record.employid);

  Object.keys(record).forEach(key =&gt; {
    $row.find('.' + key).text(record[key]);
  });
});
</code></pre>
<p>Version 2, jQuery and DOM access</p>
<pre><code>const keys = Object.keys(jsondata[0]);

$.each(jsondata, (_, record) =&gt; {
  const row = document.getElementById(record.employid);
  keys.forEach(key =&gt;
    row.querySelector('.' + key)?.textContent = record[key]
  );
});
</code></pre>
<p>But then why jQuery?</p>
<pre><code>jsondata.forEach(record =&gt; {
  const row = document.getElementById(record.employid);
  if (!row) return;

  Object.keys(record).forEach(key =&gt; {
    row.querySelector('.' + key)?.textContent = record[key];
  });
});
</code></pre>
